        int[] neighbors = new int[n];
        for (int i = 0; i < edges.length; i++) {
            if (edges[i][0] == node) {
                neighbors[i] = edges[i][1];
            } else if (edges[i][1] == node) {
                neighbors[i] = edges[i][0];
            }
        }
        return neighbors;
    }
}
